use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list.len() == list.len(),
        // new_list = list[n..] ++ list[..n]
        new_list@ == list@.subrange(n as int, list.len() as int)
                        + list@.subrange(0, n as int),
{
    let len = list.len();
    debug_assert!(len > 0);
    debug_assert!(n > 0 && n < len);

    let mut new_list = Vec::with_capacity(len);

    new_list.extend_from_slice(&list[n..]);
    new_list.extend_from_slice(&list[..n]);

    // Help Verus connect the concrete slice operations to the abstract sequence.
    assert(list@.subrange(n as int, len as int).len() == (len - n) as int);
    assert(list@.subrange(0, n as int).len() == n as int);
    assert(
        (list@.subrange(n as int, len as int) + list@.subrange(0, n as int)).len()
        == len as int
    );

    new_list
}

} // verus!